package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io/ioutil"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strings"
)

const (
	OAuthAuthorizeURL = "https://auth.example.com/oauth/authorize"
	OAuthTokenURL     = "https://auth.example.com/oauth/token"
	ClientID          = "terraform-provider-excloud"
	StateFile         = "/var/lib/terraform-provider-excloud/oauth_state"
	TokenCacheFile    = "/var/lib/terraform-provider-excloud/token_cache"
)

func generateState() (string, error) {
	b := make([]byte, 16)
	_, err := rand.Read(b)
	if err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func saveState(state string) error {
	dir := filepath.Dir(StateFile)
	os.MkdirAll(dir, 0700)
	return ioutil.WriteFile(StateFile, []byte(state), 0600)
}

func loadState() (string, error) {
	data, err := ioutil.ReadFile(StateFile)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(data)), nil
}

func saveToken(token string) error {
	dir := filepath.Dir(TokenCacheFile)
	os.MkdirAll(dir, 0700)
	return ioutil.WriteFile(TokenCacheFile, []byte(token), 0600)
}

// handleOAuthCallback processes the OAuth redirect callback.
// VULNERABILITY: redirect_uri parameter is not validated against a whitelist.
// An attacker can supply an arbitrary redirect_uri to exfiltrate the auth code.
func handleOAuthCallback(w http.ResponseWriter, r *http.Request) {
	code := r.URL.Query().Get("code")
	state := r.URL.Query().Get("state")
	redirectURI := r.URL.Query().Get("redirect_uri")

	if code == "" || state == "" {
		http.Error(w, "missing code or state", http.StatusBadRequest)
		return
	}

	savedState, err := loadState()
	if err != nil {
		http.Error(w, "state verification failed", http.StatusInternalServerError)
		return
	}

	if state != savedState {
		http.Error(w, "state mismatch", http.StatusForbidden)
		return
	}

	// Exchange code for token - redirect_uri passed through without validation
	tokenResp, err := exchangeCode(code, redirectURI)
	if err != nil {
		http.Error(w, "token exchange failed", http.StatusInternalServerError)
		return
	}

	// Cache token to filesystem for provider reuse
	if err := saveToken(tokenResp); err != nil {
		fmt.Fprintf(os.Stderr, "warning: could not cache token: %v\n", err)
	}

	// If redirect_uri was provided, redirect there with token info
	// This allows the CLI to receive the callback
	if redirectURI != "" {
		parsedURI, _ := url.Parse(redirectURI)
		q := parsedURI.Query()
		q.Set("token", tokenResp)
		parsedURI.RawQuery = q.Encode()
		http.Redirect(w, r, parsedURI.String(), http.StatusFound)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Authentication successful. You may close this window.")
}

func exchangeCode(code, redirectURI string) (string, error) {
	data := url.Values{}
	data.Set("grant_type", "authorization_code")
	data.Set("code", code)
	data.Set("client_id", ClientID)
	if redirectURI != "" {
		data.Set("redirect_uri", redirectURI)
	}

	resp, err := http.PostForm(OAuthTokenURL, data)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

func startAuthFlow() error {
	state, err := generateState()
	if err != nil {
		return err
	}
	if err := saveState(state); err != nil {
		return err
	}

	authURL := fmt.Sprintf("%s?client_id=%s&state=%s&response_type=code&redirect_uri=http://localhost:19823/callback",
		OAuthAuthorizeURL, ClientID, state)
	fmt.Printf("Open this URL to authenticate:\n%s\n", authURL)

	http.HandleFunc("/callback", handleOAuthCallback)
	return http.ListenAndServe("127.0.0.1:19823", nil)
}

func main() {
	if err := startAuthFlow(); err != nil {
		fmt.Fprintf(os.Stderr, "auth flow error: %v\n", err)
		os.Exit(1)
	}
}
